import sys,json,hashlib,argparse
from pathlib import Path
import numpy as np
ap=argparse.ArgumentParser();ap.add_argument('--root',type=Path,default=Path(__file__).resolve().parents[1]);ap.add_argument('--schedule',type=Path,required=True);ap.add_argument('--output',type=Path,required=True);args=ap.parse_args();R=args.root.resolve();sys.path.insert(0,str(R));from fast_eos import FastEOS
s=json.loads(args.schedule.read_text());cache=json.loads((R/'open-loop-redesign/collector-inputs.json').read_text());ys=json.loads((R/'component-design/material-cycle-validation.json').read_text())['loaded_stages'];eos=FastEOS();out={}
for cat,c in cache['stages'].items():
 d=c['record'];p=c['initial'];tag=d['stage'];m=np.array(p['mass_fraction_of_total'])*d['mass_kg'];r=np.r_[0.,p['outer_radius_m']];rho=m/(4*np.pi/3*np.diff(r**3));y=ys[cat]['initial_Y'];Z={'p':1,'c12':6,'c13':6,'n14':7,'n15':7};ye=sum(Z.get(k,0)*v for k,v in y.items());yi=sum(y.values());u=eos.state(rho/1000,np.array(p['T_K']),np.full(len(m),ye),np.full(len(m),yi)).e*1e-4
 core=s['central_seed_mass_and_energy'][tag];Ui=sum(cel['mass_kg']*u[cel['cell']] for cel in core['cells']);M=core['core_mass_kg'];v=(2*Ui/M)**.5;rad=core['core_outer_radius_m'];tau=.001*M/(4*np.pi*rad**2/3)
 out[tag]={'core_mass_kg':M,'core_fraction':.001,'core_outer_radius_m':rad,'core_internal_J':Ui,'core_original_kinetic_J':core['core_initial_kinetic_J'],'core_total_fraction_pulse_prepared':(Ui+core['core_initial_kinetic_J'])/d['initial_energy_J'],'opposing_packet_relative_speed_for_internal_J_m_s':v,'ballistic_delivery_time_s':(1.1e9-rad)/v,'fixed_grey_uniform_core_tau':tau,'fixed_grey_diffusion_scale_s':3*tau*rad/299792458,'whole_initial_internal_reconstruction_relative_error':float(m@u/d['initial_internal_energy_J']-1)}
args.output.write_text(json.dumps({'scope':'Energy matching of an alternative central0.1%seed assembly; no collision/3D or entropy-history simulation. Packet kinetic energy replaces existing coreinternalenergy; it is not automatically extra preparation. Opacity is the same fixedgrey diagnostic as frozenhydro.','stages':out,'code_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()},indent=2)+'\n');print(json.dumps(out,indent=2))
